extension Engine where Policy == StaticLiftPolicy {
    /// Raises `text.given` with its payload, binding the event and the payload's
    /// values in one call so the pairing of a name and a type cannot be
    /// constructed inconsistently (NL-to-IR Item C1 Path A). Both carriers are
    /// filled: the typed one a native expression reads, and `data`, which is what
    /// every other reader of `_event.data` binds it from.
    public func raiseTextGiven(text: String) {
        raiseExternalWithMeta(
            EventWithMetadata(
                StaticLiftEvent.textGiven,
                metadata: EventMetadata(
                    data: payloadJSON(.text("text", text)),
                    eventType: .externalEvent,
                    typedPayload: StaticLiftTextGivenPayload(text: text)
                )
            )
        )
    }

    /// Raises `text.kept` with its payload, binding the event and the payload's
    /// values in one call so the pairing of a name and a type cannot be
    /// constructed inconsistently (NL-to-IR Item C1 Path A). Both carriers are
    /// filled: the typed one a native expression reads, and `data`, which is what
    /// every other reader of `_event.data` binds it from.
    public func raiseTextKept(text: String) {
        raiseExternalWithMeta(
            EventWithMetadata(
                StaticLiftEvent.textKept,
                metadata: EventMetadata(
                    data: payloadJSON(.text("text", text)),
                    eventType: .externalEvent,
                    typedPayload: StaticLiftTextKeptPayload(text: text)
                )
            )
        )
    }
